There are, however, obstacles to a direct adaption: (1)
The threshold algorithm usually requires that the maximized function is monotone and submodular. In contrast, the RUWSM problem is about maximizing $h=f-c$, where $h$ can be non-monotone or non-submodular;
(2) The running time is unbounded since it will use the maximal density (unbounded for a general $f$) to initialize the global threshold.

For any set $S \subseteq T \subseteq V$ and $x \in V \setminus T$, a set function $f:2^V \rightarrow \mathbb{R}^{\geq 0}$ is submodular if
    \begin{equation} f(S \cup \{x\})-f(S)\geq f(T \cup \{x\})-f(T).
\end{equation}

\caption{\textsc{UP}($f, c, \gamma, \epsilon$)} \begin{algorithmic}[1]
   \STATE {\bfseries Input:} utility function $f$, cost function $c$, submodularity ratio $\gamma$, error threshold $\epsilon$.
   \STATE {\bfseries Output:} $\Tilde{S} = arg\,max_{S_i, i \in [n]} f(S_i)-c(S_i)$.
   \STATE $S_0 \gets \emptyset$; $i\gets 1$
    \STATE $u(e) \gets 0$ for all $e \in V$ 
    \STATE $PQ \gets$ priority\_queue$(\{(\frac{f(e)}{c(e)}, e) \mid e \in V\})$
    \WHILE{True}
    \STATE Remove entries from $PQ$ where the density(key) $\leq \gamma$
        \IF{PQ is empty}
            \STATE \textsc{Terminate the Algorithm}  
        \ENDIF
        \STATE $(\tau_i, v_i) \gets PQ.getTopAndRemove()$ 
        \STATE $u(v_i)++$ 
        \IF{$\frac{f(v_i|S_{i-1})}{c(v_i)} \geq \max\{\gamma, (1-\epsilon)\tau_i \}$}
            \STATE $S_i \gets S_{i-1} \cup \{v_i\}$
            \STATE $i++$
            \STATE \textsc{Continue to the Next Iteration} 
        \ENDIF
        \IF{$u(v_i) \leq \frac{\log \frac{n}{\gamma \epsilon}}{\epsilon}$}
            \STATE $PQ.push((\frac{f(v_i|S_{i-1})}{c(v_i)}, v_i)$) 
        \ENDIF    
    \ENDWHILE
\end{algorithmic}

Since $v_i$ is the element added to $S_{i-1}$ at line~14 of the algorithm,
$\frac{f(v_i|S_{i-1})}{c(v_i)}\geq {(1-\epsilon)\tau_i}$ is satisfied. Furthermore, for every 
$\forall u\in {\rm OPT} \setminus S_{i-1}$, $u$ is either equal to $v_i$ or does not satisfy the condition in line~13. Hence, 
\begin{equation}
\frac{f(v_i|S_{i-1})}{c(v_i)}\geq {(1-\epsilon)\tau_i} \geq (1-\epsilon) \frac{f(u|S_{i-1})}{c(u)}. \end{equation}

We then derive the following inequality.
\begin{align*}
    & f({\rm OPT})-f(S_{i-1}) \leq \frac{1}{\gamma} \sum_{u\in {\rm OPT} \setminus S_{i-1}} f(u|S_{i-1}) \quad\mbox{\tt  by Def.~(\ref{def:weak-sub})} \\
    &\leq \frac{1}{\gamma} \sum_{u\in {\rm OPT} \setminus S_{i-1}} \frac{c(u)}{1-\epsilon} \cdot \frac{f(v_i|S_{i-1})}{c(v_i)}  \quad\quad\quad\mbox{\tt  due to Eq.~(\ref{eq:i-2})} \\
    &\leq \frac{1}{\gamma(1-\epsilon)} \frac{f(v_i|S_{i-1})}{c(v_i)} c({\rm OPT}).
\end{align*}

Rearranging the last inequality concludes the proof.

For all $i\in [1,\ell]$, if $v_i$ is the element added to $S_{i-1}$ and $f(S_{i})=f(S_{i-1} \cup \{v_i\})$, then
\begin{equation} f(S_{i}) \geq \left(   1- \prod_{s=1}^{i} \left(1- \gamma(1-\epsilon) \frac{c(v_i)}{c({\rm OPT})} \right)   \right) f({\rm OPT}).
\end{equation}

Combining the above inequality with the Case 1 condition ($\gamma (1-\epsilon)c(S_\ell) < A$), we have 
     \begin{align*}
         f(\Tilde{S})-c(\Tilde{S})& \geq f(S_\ell)-c(S_\ell)\geq (1-\epsilon)f({\rm OPT})-c({\rm OPT})-\frac{1}{\gamma (1-\epsilon)}A.
     \end{align*}
    {This concludes the proof of the theorem for Case 1}. \hfill $\Box$

In this case, there exist $t\in[1, \ell]$ such that:
    \begin{equation}
        c(S_{t-1})< \frac{1}{\gamma (1-\epsilon)} A  \leq c(S_t) \end{equation}
    We further divide Case 2 into two sub-cases: (2.1) and (2.2).

\begin{claim} Under the Case 2.2, the following holds: $\forall~ j \in [1, t-1]:~ c(v_j) \leq c({\rm OPT})$.
\end{claim}
{\sc Proof Sketch:} We prove this claim by contradiction. Assume there exist some $j \in [1, t-1]$ that $c(v_j)>c({\rm OPT})$. Under Case 2.2 condition, $f(S_j) < \gamma(1-\epsilon)f({\rm OPT})$ is true. Then if we apply Lemma~\ref{lem:marginal-gain} to $f(v_j|S_{j-1})$ of $f(S_j)= f(S_{j-1}) + f(v_j|S_{j-1})$, we can derive $f(S_j) \geq \gamma(1-\epsilon)f({\rm OPT})$, which is a contradiction. \hfill $\Box$

\begin{claim} Under the Case 2.2, if we denote $B_j = A-\gamma(1-\epsilon) c(S_{j})$, then we have  $c(v_t) > B_{t-1}$.
\end{claim}

\begin{proof}
\begin{align*}
    c(v_t) &= c(S_t) - c(S_{t-1}) \ \geq \frac{1}{\gamma(1-\epsilon)}A- c(S_{t-1}) \\
    &= \frac{1}{\gamma(1-\epsilon)}\big(A-\gamma (1-\epsilon)c(S_{t-1})\big) \\
       & \geq   A- \gamma (1-\epsilon)c(S_{t-1})\ = \ B_{t-1}.
\end{align*}
The first inequality follows from the case 2 condition Eq.~(\ref{eq:th1-case2}).
\end{proof}

We have proved the approximation guarantee of Theorem \ref{th:unconstrained} for every case. The following lemma finishes the proof of Theorem \ref{th:unconstrained} by bounding the worst-case running time of Algorithm \ref{alg:up}. 

\begin{lemma} The time complexity of Algorithm \ref{alg:up} is 

    $\mathcal{O}(\frac{n}{\epsilon} \log \frac{n}{\epsilon \gamma})$.
\end{lemma}
\begin{proof}
    As per line 18 of Algorithm \ref{alg:up}, each element $e \in V$ can be evaluated for at most $(\log \frac{n}{\gamma \epsilon})/{\epsilon}$ times. Each such consideration involves one oracle call to the function $f$. Therefore, the maximal total number of oracle calls for $n$ elements is $n \cdot (\log \frac{n}{\gamma \epsilon})/{\epsilon} \in \mathcal{O}(\frac{n}{\epsilon} \log \frac{n}{\epsilon \gamma})$. 
\end{proof}

\begin{align*}
    c(v_t) &= c(S_t) - c(S_{t-1}) \ \geq \frac{1}{\gamma(1-\epsilon)}A- c(S_{t-1}) \\
    &= \frac{1}{\gamma(1-\epsilon)}\big(A-\gamma (1-\epsilon)c(S_{t-1})\big) \\
       & \geq   A- \gamma (1-\epsilon)c(S_{t-1})\ = \ B_{t-1}.
\end{align*}
The first inequality follows from the case 2 condition Eq.~(\ref{eq:th1-case2}).

We first solve the right hands side of the inequality by splitting it into a part with $f(S_{j})$ and without $f(S_{j})$. Then we can further apply Lemma~\ref{lem:f-Si} to the former.
\end{itemize}
\begin{align*}
    & \displaystyle\frac{B_j(f({\rm OPT}) - f(S_{j}))}{c({\rm OPT})} +f(S_{j}) = \displaystyle\left(1-\frac{B_j}{c({\rm OPT})}\right)f(S_{j}) + \frac{B_j}{c({\rm OPT})}f({\rm OPT})\\
    &\geq  \displaystyle\left(1-\frac{B_j}{c({\rm OPT})}\right)\underbrace{\left(   1- \prod_{k=1}^{j}  \left(1- \gamma(1-\epsilon) \frac{c(v_k)}{c({\rm OPT})} \right)   \right) f({\rm OPT})}_{\mbox{\tt follows from Lemma~\ref{lem:f-Si}}} +\displaystyle\frac{B_j}{c({\rm OPT})}f({\rm OPT})\\
        &=f({\rm OPT}) - \displaystyle\left(\left(1-\frac{B_j}{c({\rm OPT})}\right)\prod_{k=1}^{j} \left(1- \gamma(1-\epsilon) \frac{c(v_k)}{c({\rm OPT})} \right)\right)f({\rm OPT})\\
        &=\left( 1- \displaystyle\left(1-\frac{B_j}{c({\rm OPT})}\right)\prod_{k=1}^{j} \left(1- \gamma(1-\epsilon) \frac{c(v_k)}{c({\rm OPT})} \right) \right)f({\rm OPT})\\
        &\geq \left( 1- \displaystyle\left(1- \frac{B_j+\gamma(1-\epsilon)\cdot \sum_{k=1}^{j}c(v_k)}{(j+1)\cdot c({\rm OPT})} \right)^{j+1} \right)f({\rm OPT})
\end{align*}

Note that, in Claim \ref{claim:cost-St}, we have established $c(v_t)\geq B_{t-1}$. Furthermore, from Corollary \ref{col:lower-opt}, we know
$f({\rm OPT}) - f(S_j) \geq \frac{1}{\gamma(1-\epsilon)}{c({\rm OPT})}$. Therefore, 



the residual value is non-negative. Hence, 
\begin{align*}
   &f(\Tilde{S})-c(\Tilde{S}) \geq f(S_t)-c(S_t)\geq \gamma(1-\epsilon)f({\rm OPT})-c({\rm OPT})-\frac{1}{\gamma (1-\epsilon)}A.
\end{align*}

Suppose the input utility function is $\delta$-approximate to a monotone $\gamma$-submodular set function $f$, $c$ is a modular cost function, $\epsilon \in (0,1)$ is an error threshold. Let ${\rm OPT} =  arg\,max_{T \subseteq V}\{f(T)-c(T)\}$, after $\mathcal{O}(\frac{n}{\epsilon}\log \frac{n}{\gamma \epsilon})$ oracle calls to the $\delta$-approximate utility function,  Algorithm \ref{alg:up} outputs $\Tilde{S}$ such that
    \begin{align*}
        f(\Tilde{S})-c(\Tilde{S}) \geq &\gamma(1-\epsilon)f({\rm OPT})-c({\rm OPT})-\frac{1}{\gamma (1-\epsilon)}A \\
        &\quad\quad- 2\delta\left(\beta+ \frac{n}{\gamma} + 1 + n(1-\epsilon)\beta'\right)
    \end{align*}
    where $A = c({\rm OPT}) \log \frac{f({\rm OPT})}{c({\rm OPT})}$, $\beta = \frac{c({\rm OPT})}{c_{\min}}$ and $\beta' = \frac{c_{max}}{c({\rm OPT})}$.

