\caption{\textsc{$\gamma$-ROI}($f, c, \gamma$)} \begin{algorithmic}[1]
   \STATE {\bfseries Input:} utility function $f$, cost function $c$, submodularity ratio $\gamma$.
   \STATE {\bfseries Output:} $\Tilde{S} = arg\,max_{S_i, i \in [n]} f(S_i)-c(S_i)$.
   \vspace{.05in}
   \STATE $S_0 \gets \emptyset$
    \FOR{$i\gets 1$ to $n$}
    \STATE $v_i \gets arg\,max_{u \in V \setminus S_{i-1}} \frac{f(u \mid S_{i-1})}{c(u)}$
        \IF{$f(u \mid S_{i-1}) > \gamma \cdot c(u)$}
            \STATE $S_i \gets S_{i-1} \cup \{v_i\}$  
        \ELSE
        \STATE {\sc Break}
        \ENDIF 
    \ENDFOR
\end{algorithmic}

