$\forall u\in {\rm OPT} \setminus S_{i-1}$, $u$ was not the element selected with the maximal density w.r.t.  $f(S_{i-1})$. Hence, 
\begin{equation}
\frac{f(v_i|S_{i-1})}{c(v_i)}\geq \frac{f(u|S_{i-1})}{c(u)} \end{equation}

For all $i\in [1,\ell]$ and if $v_i$ is the element added to $S_{i-1}$ in the $i$-th iteration then
\begin{equation} f(S_{i}) \geq \left(1- \prod_{s=1}^{i} \left(1- \gamma \frac{c(v_i)}{c({\rm OPT})} \right)   \right) f({\rm OPT})
\end{equation}

\caption{\textsc{threshold-ROI}($f, c, \gamma$)} \begin{algorithmic}[1]
   \STATE {\bfseries Input:} utility function $f$, cost function $c$, submodularity ratio $\gamma$.
   \STATE {\bfseries Output:} $\Tilde{S} = arg\,max_{S_i, i \in [n]} f(S_i)-c(S_i)$.
   \vspace{.05in}
   \STATE $\tau \gets \max_{u \in V}\frac{f(u)}{c(u)}$, $S_0 \gets \emptyset$, $i \gets 1$
    \WHILE{$\tau > \gamma$}
    \FOR{$e \in V \setminus S_{i-1}$}
    \IF{$\frac{f(e\mid S_{i-1})}{c(e)} \geq \tau$}
    \STATE $S_i \gets S_{i-1} \cup \{e\}$
    \STATE $i++$
    \ENDIF
    \ENDFOR
    \STATE $\tau \gets (1-\epsilon) \tau$
    \ENDWHILE
\end{algorithmic}

The proof method of the theoretical bound of Theorem \ref{th:unconstrained-thresh} is similar to the previous theorems. We first prove the lower bound of the marginal gain when adding an element to the seed set. Then, we prove the theorem by cases.

\begin{lemma} For all $i$ such that $1 \leq i \leq \ell$ and if $v_i$ be the element added to $S_{i-1}$ then
\[ 
f(v_i|S_{i-1}) \geq \gamma(1-\epsilon) \frac{c(v_i)}{c({\rm OPT})} \big ( f({\rm OPT}) - f(S_{i-1}) \big ) 
\]
\end{lemma}

\begin{proof}

 Let $\tau_i$ be the value of $\tau$ at some iteration. By the algorithm, we know that $v_i$ was not selected for the previous $\tau_{i-1}$ where
$\tau_{i-1} = \frac{\tau_i}{1-\epsilon}$. In other words, 
\begin{equation}
\forall ~ u\in {\rm OPT} \setminus S_{i-1}: \frac{f(u|S_{i-1})}{c(u)}\leq \frac{\tau_i}{1-\epsilon} \end{equation}

Since $v_i$ is added to $S_{i-1}$, we have: 
\begin{align*}
    & f({\rm OPT})-f(S_{i-1}) \leq \frac{1}{\gamma} \sum_{u\in {\rm OPT} \setminus S_{i-1}} f(u|S_{i-1}) \quad\mbox{\tt  by Def.~(\ref{def:weak-sub})} \\
    &\leq \frac{1}{\gamma} \sum_{u\in {\rm OPT} \setminus S_{i-1}} \frac{c(u)}{1-\epsilon} \cdot \frac{f(v_i|S_{i-1})}{c(v_i)}  \quad\quad\quad\mbox{\tt  due to Eq.~(\ref{eq:i-2})} \\
    &\leq \frac{1}{\gamma(1-\epsilon)} \frac{f(v_i|S_{i-1})}{c(v_i)} c({\rm OPT}).
\end{align*}













\end{proof}










\textbf{\textit{Notice that the above lemma gives the same property as in the proof of Theorem \ref{th:unconstrained}. The remaining proofs of Theorem \ref{th:unconstrained-thresh} are the same as the corresponding proofs of Theorem \ref{th:unconstrained}.
Therefore, readers can find the rest of the proofs in the main paper. We jump right to the running time analysis.}}





















































































\begin{lemma} The time complexity of Algorithm~\ref{alg:roi-threshold} is $\mathcal{O}(\frac{n}{\epsilon}\log \frac{\tau}{\epsilon})$. 
\end{lemma}


The for-loop runs at most $n$ times for each choice of threshold $\tau$. Let $\tau_0 = \max_{e \in V}\{\frac{f(e)}{c(e)}\}$ be the initial threshold. We know that $\gamma$ is the threshold at termination of the algorithm. If $T$ is the number of runs of the while-loop, then
\[
T = 2+\log_{(1-\epsilon)^{-1}} \frac{\tau_0}{\gamma} = 2-\frac{\ln \tau_0-\ln \gamma}{\ln 1-\epsilon}
\leq 2+\epsilon^{-1} (\ln \tau_0 -\ln \gamma) \in O(\epsilon^{-1} \log \tau_0)
\]

So, the overall run time is $\mathcal{O}(\frac{n}{\epsilon}\log \tau_0)$.

\begin{lemma} For all $i$ such that $1 \leq i \leq \ell$ and if $v_i$ be the element added to $S_{i-1}$ then
\[ 
f(v_i|S_{i-1}) \geq \gamma(1-\epsilon) \frac{c(v_i)}{c({\rm OPT})} \big ( f({\rm OPT}) - f(S_{i-1}) \big ) 
\]
\end{lemma}

